52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.context.request.RequestAttributes;
57	import org.springframework.web.context.request.RequestContextHolder;
58	import org.springframework.web.context.request.ServletRequestAttributes;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
74	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
75	     */
76	    /**
77	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
78	     * they can be routed and asserted independently of the application's diagnostic logging.
79	     */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    private static final Pattern EMAIL_PATTERN =
83	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
84	
85	    /**
86	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
87	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Common address abbreviations expanded to their full form during address normalization.
94	     * Matching is performed per whitespace-separated token on the upper-cased value.
95	     */
96	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
97	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
98	
99	    /**
100	     * Required national-number length (the digits after the country code) per E.164 country code.
101	     * A number whose country code appears here must carry exactly the mapped number of national
102	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
103	     */
104	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
105	        Map.of("61", 9, "1", 10);
106	
107	    /**
108	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
109	     * validating an owner's postcode against the region derived from its city. A region not listed
110	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
111	     * any 4-digit postcode is accepted.
112	     */
113	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
114	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
115	
116	    /**
117	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
118	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
119	     * no postcode-range constraint.
120	     */
121	    private static final Map<String, String> CITY_REGION = Map.of(
122	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
123	
124	    /**
125	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
126	     * repeats with a token already seen, the originally created owner is returned rather than a
127	     * duplicate being made.
128	     */
129	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
130	
131	    /**
132	     * Maps each seen {@code Idempotency-Key} to the id of the owner its first successful create
133	     * produced, so a repeat with the same key returns that owner instead of creating a duplicate.
134	     */
135	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
136	
137	    private final ClinicService clinicService;
138	
139	    private final OwnerMapper ownerMapper;
140	
141	    private final PetMapper petMapper;
142	
143	    private final VisitMapper visitMapper;
144	
145	    public OwnerRestControllerV1(ClinicService clinicService,
146	                                 OwnerMapper ownerMapper,
147	                                 PetMapper petMapper,
148	                                 VisitMapper visitMapper) {
149	        this.clinicService = clinicService;
150	        this.ownerMapper = ownerMapper;
151	        this.petMapper = petMapper;
152	        this.visitMapper = visitMapper;
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
158	        Collection<Owner> owners;
159	        if (lastName != null) {
160	            owners = this.clinicService.findOwnerByLastName(lastName);
161	        } else {
162	            owners = this.clinicService.findAllOwners();
163	        }
164	        if (owners.isEmpty()) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
183	        HttpHeaders headers = new HttpHeaders();
184	        String idempotencyKey = currentIdempotencyKey();
185	        if (idempotencyKey != null) {
186	            Integer existingId = idempotentCreates.get(idempotencyKey);
187	            if (existingId != null) {
188	                Owner existing = this.clinicService.findOwnerById(existingId);
189	                if (existing != null) {
190	                    // Repeat of a create already performed under this key: return the original
191	                    // owner with 200 instead of creating a duplicate.
192	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
193	                }
194	            }
195	        }
196	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
197	        LocalDate suppliedDate = owner.getRegistrationDate();
198	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
199	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
200	        }
201	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
202	        LocalDate registrationDate = toBusinessDay(effectiveDate);
203	        owner.setRegistrationDate(registrationDate);
204	        long createdToday = this.clinicService.findAllOwners().stream()
205	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
206	            .count();
207	        if (createdToday >= 100) {
208	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
209	        }
210	        owner.setBulkSignupWarning(createdToday > 80);
211	        if (!applyAddress(owner)) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        String telephone = toE164(owner.getTelephone());
215	        if (telephone == null) {
216	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
217	        }
218	        owner.setTelephone(telephone);
219	        if (owner.getEmail() != null) {
220	            String email = normalizeEmail(owner.getEmail());
221	            if (!EMAIL_PATTERN.matcher(email).matches()) {
222	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
223	            }
224	            if (isDisposableEmailDomain(email)) {
225	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
226	            }
227	            owner.setEmail(email);
228	        }
229	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        String cityKey = householdKey(owner.getCity());
233	        long cityCount = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> existing.getCity() != null
235	                && cityKey.equals(householdKey(existing.getCity())))
236	            .count();
237	        if (cityCount >= 50) {
238	            return new ResponseEntity<>(HttpStatus.CONFLICT);
239	        }
240	        // The household is keyed on (normalized last name, postcode): every owner derives the same
241	        // deterministic householdId from those two fields, so owners sharing them are the same
242	        // household. This computed id is what duplicate detection and the household size below key off.
243	        String householdId = householdId(owner);
244	        owner.setHouseholdId(householdId);
245	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
246	            .filter(existing -> !existing.getDeleted())
247	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
248	            .toList();
249	        owner.setHouseholdSize(householdMembers.size() + 1);
250	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
251	        // Household-duplicate block: a second owner in an existing household (same computed
252	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
253	        // declaring the new owner a member — rather than creating the household link itself.
254	        if (!householdMembers.isEmpty() && !sharesHousehold) {
255	            return new ResponseEntity<>(HttpStatus.CONFLICT);
256	        }
257	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
258	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
259	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
260	        // telephone is part of the key, two household members with different telephones are allowed.
261	        // This still catches a full identity repeat even when it declares sharesHousehold.
262	        String identityKey = owner.getIdentityKey();
263	        boolean identityInUse = this.clinicService.findAllOwners().stream()
264	            .filter(existing -> !existing.getDeleted())
265	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
266	        if (identityInUse) {
267	            return new ResponseEntity<>(HttpStatus.CONFLICT);
268	        }
269	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
270	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
271	        // different telephone is now, by definition, a household duplicate already rejected above, so
272	        // it never reaches this point; the check is retained for owners that are not household matches.
273	        if (sharesHousehold) {
274	            owner.setPossibleDuplicate(false);
275	        } else {
276	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
277	            String softDuplicatePostcode = owner.getPostcode();
278	            String softDuplicateTelephone = owner.getTelephone();
279	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
280	                : this.clinicService.findAllOwners().stream()
281	                    .filter(existing -> !existing.getDeleted())
282	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
283	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
284	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
285	                    .min(Comparator.comparing(Owner::getId))
286	                    .orElse(null);
287	            if (possibleDuplicate != null) {
288	                owner.setPossibleDuplicate(true);
289	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
290	            } else {
291	                owner.setPossibleDuplicate(false);
292	            }
293	        }
294	        owner.setCustomerCode(customerCode(owner));
295	        String firstNameKey = householdKey(owner.getFirstName());
296	        String namesakeLastNameKey = householdKey(owner.getLastName());
297	        long namesakeCount = this.clinicService.findAllOwners().stream()
298	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
299	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
300	            .count();
301	        owner.setNamesakeCount((int) namesakeCount);
302	        this.clinicService.saveOwner(owner);
303	        if (idempotencyKey != null) {
304	            idempotentCreates.put(idempotencyKey, owner.getId());
305	        }
306	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
307	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
308	            owner.getMembershipLevel(), owner.getMembershipNumber());
309	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
310	        headers.setLocation(UriComponentsBuilder.newInstance()
311	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
312	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
313	    }
314	
315	    /**
316	     * Validates an owner's postcode against the region derived from its city. The postcode is
317	     * optional: a {@code null} value is always accepted. When present it must fall within the
318	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
319	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
320	     * The 4-digit syntax itself is enforced upstream by bean validation.
321	     *
322	     * @param postcode the owner's postcode (may be {@code null})
323	     * @param locality the region derived from the owner's city
324	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
325	     *         within the region's range; {@code false} when it is out of range
326	     */
327	    /**
328	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
329	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
330	     *
331	     * @param city the owner's city (may be {@code null})
332	     * @return the canonical region, or {@code "UNKNOWN"}
333	     */
334	    /**
335	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
336	     * header is absent, blank, or no servlet request is bound to the current thread.
337	     *
338	     * @return the idempotency key, or {@code null}
339	     */
340	    private String currentIdempotencyKey() {
341	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
342	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
343	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
344	            if (key != null && !key.isBlank()) {
345	                return key.trim();
346	            }
347	        }
348	        return null;
349	    }
350	
351	    private String regionForCity(String city) {
352	        if (city == null) {
353	            return "UNKNOWN";
354	        }
355	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
356	    }
357	
358	    private boolean isPostcodeValidForCity(String postcode, String locality) {
359	        if (postcode == null) {
360	            return true;
361	        }
362	        int[] range = REGION_POSTCODES.get(locality);
363	        if (range == null) {
364	            return true;
365	        }
366	        int value = Integer.parseInt(postcode);
367	        return value >= range[0] && value <= range[1];
368	    }
369	
370	    /**
371	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
372	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
373	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
374	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
375	     * recognised country codes the national number (the digits after the country code) must also be
376	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
377	     * needs 10); a wrong national-number length yields {@code null}.
378	     *
379	     * @param telephone the raw telephone value (may be {@code null})
380	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
381	     *         a valid E.164 number
382	     */
383	    private String toE164(String telephone) {
384	        if (telephone == null) {
385	            return null;
386	        }
387	        String trimmed = telephone.trim();
388	        boolean hasCountryCode = trimmed.startsWith("+");
389	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
390	        if (hasCountryCode) {
391	            cleaned = cleaned.substring(1);
392	        }
393	        if (!cleaned.matches("[0-9]+")) {
394	            return null;
395	        }
396	        String digits;
397	        if (hasCountryCode) {
398	            digits = cleaned;
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (digits.length() < 8 || digits.length() > 15) {
404	            return null;
405	        }
406	        if (!hasValidNationalNumberLength(digits)) {
407	            return null;
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Checks the national-number length of an E.164 digit string (country code plus national
414	     * number, without the leading {@code '+'}) against its country code. When the number's country
415	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
416	     * country code must number exactly what that country requires; the longest matching country
417	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
418	     * only by the generic total-length rule).
419	     *
420	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
421	     * @return {@code true} if the national-number length is acceptable for the country code
422	     */
423	    private boolean hasValidNationalNumberLength(String digits) {
424	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
425	            .filter(entry -> digits.startsWith(entry.getKey()))
426	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
427	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
428	            .orElse(true);
429	    }
430	
431	    /**
432	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
433	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
434	     *
435	     * @param email the raw email value (must not be {@code null})
436	     * @return the trimmed, lower-cased email
437	     */
438	    private String normalizeEmail(String email) {
439	        return email.trim().toLowerCase(Locale.ROOT);
440	    }
441	
442	    /**
443	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
444	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
445	     * an email without an {@code '@'} carries no blocked domain.
446	     *
447	     * @param email the trimmed, lower-cased email
448	     * @return {@code true} when the email's domain is blocklisted
449	     */
450	    private boolean isDisposableEmailDomain(String email) {
451	        int at = email.lastIndexOf('@');
452	        if (at < 0) {
453	            return false;
454	        }
455	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
456	    }
457	
458	    /**
459	     * Applies the owner's address, preferring the structured form over the flat one. When a
460	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
461	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
462	     * non-blank {@code addressLine2} is present, by a single space and the normalized
463	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
464	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
465	     * is invalid.
466	     *
467	     * @param owner the owner whose address fields are normalized and composed in place
468	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
469	     */
470	    private boolean applyAddress(Owner owner) {
471	        String line1 = owner.getAddressLine1();
472	        if (line1 != null && !line1.isBlank()) {
473	            String normalizedLine1 = normalizeAddress(line1);
474	            owner.setAddressLine1(normalizedLine1);
475	            String composed = normalizedLine1;
476	            String line2 = owner.getAddressLine2();
477	            if (line2 != null && !line2.isBlank()) {
478	                String normalizedLine2 = normalizeAddress(line2);
479	                owner.setAddressLine2(normalizedLine2);
480	                composed = normalizedLine1 + " " + normalizedLine2;
481	            }
482	            owner.setAddress(composed);
483	            return true;
484	        }
485	        String address = normalizeAddress(owner.getAddress());
486	        if (address == null || address.isEmpty()) {
487	            return false;
488	        }
489	        owner.setAddress(address);
490	        return true;
491	    }
492	
493	    /**
494	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
495	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
496	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
497	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
498	     * normalized form, and every household comparison uses it.
499	     *
500	     * @param address the raw address value (may be {@code null})
501	     * @return the normalized address, or {@code null} if the input was {@code null}
502	     */
503	    private String normalizeAddress(String address) {
504	        if (address == null) {
505	            return null;
506	        }
507	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
508	        if (collapsed.isEmpty()) {
509	            return collapsed;
510	        }
511	        String[] tokens = collapsed.split(" ");
512	        StringBuilder sb = new StringBuilder(collapsed.length());
513	        for (int i = 0; i < tokens.length; i++) {
514	            if (i > 0) {
515	                sb.append(' ');
516	            }
517	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
518	        }
519	        return sb.toString();
520	    }
521	
522	    /**
523	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
524	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
525	     * so that owners are compared case-insensitively with collapsed whitespace.
526	     *
527	     * @param value the raw value (must not be {@code null})
528	     * @return the normalized comparison key
529	     */
530	    private String householdKey(String value) {
531	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
532	    }
533	
534	    /**
535	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
536	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
537	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
538	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
539	     * those two fields derives the identical identifier and therefore belongs to the same household.
540	     *
541	     * @param owner the owner whose household identifier is derived
542	     * @return the stable household identifier
543	     */
544	    private String householdId(Owner owner) {
545	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
546	        String key = householdKey(owner.getLastName()) + "|" + postcode;
547	        try {
548	            byte[] digest = MessageDigest.getInstance("SHA-256")
549	                .digest(key.getBytes(StandardCharsets.UTF_8));
550	            StringBuilder sb = new StringBuilder(digest.length * 2);
551	            for (byte b : digest) {
552	                sb.append(String.format("%02x", b));
553	            }
554	            return sb.substring(0, 12);
555	        }
556	        catch (java.security.NoSuchAlgorithmException e) {
557	            throw new IllegalStateException("SHA-256 not available", e);
558	        }
559	    }
560	
561	    /**
562	     * Builds the customer code for a newly registered owner in the form
563	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
564	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
565	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
566	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
567	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
568	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
569	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
570	     * always receive distinct customer codes.
571	     *
572	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
573	     * @return the assigned customer code
574	     */
575	    private String customerCode(Owner owner) {
576	        String region = owner.getLocality();
577	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
578	        String base = region + "-" + hash8;
579	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
580	            .map(Owner::getCustomerCode)
581	            .filter(code -> code != null)
582	            .collect(Collectors.toSet());
583	        if (!existingCodes.contains(base)) {
584	            return base;
585	        }
586	        int n = 2;
587	        while (existingCodes.contains(base + "-" + n)) {
588	            n++;
589	        }
590	        return base + "-" + n;
591	    }
592	
593	    /**
594	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
595	     * UTF-8 bytes of {@code input}.
596	     *
597	     * @param input  the value to hash
598	     * @param length the number of leading hex characters to keep
599	     * @return the truncated, upper-cased hex digest
600	     */
601	    private String sha256UpperHex(String input, int length) {
602	        try {
603	            byte[] digest = MessageDigest.getInstance("SHA-256")
604	                .digest(input.getBytes(StandardCharsets.UTF_8));
605	            StringBuilder sb = new StringBuilder(digest.length * 2);
606	            for (byte b : digest) {
607	                sb.append(String.format("%02x", b));
608	            }
609	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
610	        }
611	        catch (java.security.NoSuchAlgorithmException e) {
612	            throw new IllegalStateException("SHA-256 not available", e);
613	        }
614	    }
615	
616	    /** Fixed public holidays that the business-day roll skips. */
617	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
618	        LocalDate.parse("2026-01-01"),
619	        LocalDate.parse("2026-01-26"),
620	        LocalDate.parse("2026-04-25"),
621	        LocalDate.parse("2026-12-25"),
622	        LocalDate.parse("2026-12-28"));
623	
624	    /**
625	     * Rolls a registration date forward onto a business day. When the given date falls on a
626	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
627	     * lands on a non-holiday weekday; a business day is returned unchanged.
628	     *
629	     * @param date the effective registration date (must not be {@code null})
630	     * @return the same date if it is already a business day, otherwise the next business day
631	     */
632	    private LocalDate toBusinessDay(LocalDate date) {
633	        while (isNonBusinessDay(date)) {
634	            date = date.plusDays(1);
635	        }
636	        return date;
637	    }
638	
639	    private boolean isNonBusinessDay(LocalDate date) {
640	        DayOfWeek dayOfWeek = date.getDayOfWeek();
641	        return dayOfWeek == DayOfWeek.SATURDAY
642	            || dayOfWeek == DayOfWeek.SUNDAY
643	            || PUBLIC_HOLIDAYS.contains(date);
644	    }
645	
646	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
647	    @Override
648	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
649	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
650	        if (currentOwner == null) {
651	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
652	        }
653	        String email = ownerFieldsDto.getEmail();
654	        if (email != null) {
655	            email = normalizeEmail(email);
656	            if (!EMAIL_PATTERN.matcher(email).matches()) {
657	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
658	            }
659	        }
660	        String telephone = toE164(ownerFieldsDto.getTelephone());
661	        if (telephone == null) {
662	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
663	        }
664	        currentOwner.setAddress(ownerFieldsDto.getAddress());
665	        currentOwner.setCity(ownerFieldsDto.getCity());
666	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
667	        currentOwner.setLastName(ownerFieldsDto.getLastName());
668	        currentOwner.setTelephone(telephone);
669	        currentOwner.setEmail(email);
670	        this.clinicService.saveOwner(currentOwner);
671	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
672	    }
673	
674	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
675	    @Transactional
676	    @Override
677	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
678	        Owner owner = this.clinicService.findOwnerById(ownerId);
679	        if (owner == null) {
680	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
681	        }
682	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
683	        owner.setDeleted(true);
684	        this.clinicService.saveOwner(owner);
685	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
691	        Owner owner = this.clinicService.findOwnerById(ownerId);
692	        if (owner == null) {
693	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
694	        }
695	        HttpHeaders headers = new HttpHeaders();
696	        Pet pet = petMapper.toPet(petFieldsDto);
697	        owner.setId(ownerId);
698	        pet.setOwner(owner);
699	        pet.getType().setName(null);
700	        this.clinicService.savePet(pet);
701	        PetDto petDto = petMapper.toPetDto(pet);
702	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
703	            .buildAndExpand(pet.getId()).toUri());
704	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Override
709	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
710	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
711	        if (currentOwner != null) {
712	            Pet currentPet = this.clinicService.findPetById(petId);
713	            if (currentPet != null) {
714	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
715	                currentPet.setName(petFieldsDto.getName());
716	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
717	                this.clinicService.savePet(currentPet);
718	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
719	            }
720	        }
721	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
722	    }
723	
724	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
725	    @Override
726	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
727	        HttpHeaders headers = new HttpHeaders();
728	        Visit visit = visitMapper.toVisit(visitFieldsDto);
729	        Pet pet = new Pet();
730	        pet.setId(petId);
731	        visit.setPet(pet);
732	        this.clinicService.saveVisit(visit);
733	        VisitDto visitDto = visitMapper.toVisitDto(visit);
734	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
735	            .buildAndExpand(visit.getId()).toUri());
736	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
737	    }
738	
739	
740	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
741	    @Override
742	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
743	        Owner owner = this.clinicService.findOwnerById(ownerId);
744	        if (owner != null) {
745	            Pet pet = owner.getPet(petId);
746	            if (pet != null) {
747	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
748	            }
749	        }
750	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	    }
752	}
