426	    /**
427	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
428	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
429	     * (non-digit characters are ignored).
430	     *
431	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
432	     */
433	    public Integer getCheckDigit() {
434	        if (this.customerCode == null) {
435	            return null;
436	        }
437	        int sum = 0;
438	        boolean dbl = true;
439	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
440	            char c = this.customerCode.charAt(i);
441	            if (c < '0' || c > '9') {
442	                continue;
443	            }
444	            int d = c - '0';
445	            if (dbl) {
446	                d *= 2;
447	                if (d > 9) {
448	                    d -= 9;
449	                }
450	            }
451	            sum += d;
452	            dbl = !dbl;
453	        }
454	        return (10 - (sum % 10)) % 10;
455	    }
