457	    /**
458	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
459	     * they carry an email address, {@code 1} when they have no namesakes
460	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
461	     * members ({@code householdSize}), and {@code 3} for tenure of at least one elapsed
462	     * fiscal year (the {@code registrationDate}'s fiscal year precedes the current fiscal
463	     * year, the fiscal year starting on 1 July). Because a newly created owner is still in
464	     * the current fiscal year, a new owner can score at most {@code 5} points.
465	     *
466	     * @return the membership points
467	     */
468	    public Integer getMembershipPoints() {
469	        int points = 0;
470	        boolean hasEmail = this.email != null && !this.email.isBlank();
471	        if (hasEmail) {
472	            points += 2;
473	        }
474	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
475	        if (noNamesakes) {
476	            points += 1;
477	        }
478	        if (this.householdSize != null && this.householdSize >= 3) {
479	            points += 2;
480	        }
481	        if (this.registrationDate != null
482	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
483	            points += 3;
484	        }
485	        return points;
486	    }
