520	        return hasEmail ? "EMAIL" : "PHONE";
521	    }
522	
523	    /**
524	     * The owner's identity key: the single derived value used for duplicate detection, formed as
525	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
526	     * email are the already-normalized stored values and a {@code null} email or household id is
527	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
528	     * are equal; because the telephone is part of the key, household members with different
529	     * telephones have different identity keys.
530	     *
531	     * @return the derived identity key
532	     */
533	    public String getIdentityKey() {
534	        String telephonePart = this.telephone == null ? "" : this.telephone;
535	        String emailPart = this.email == null ? "" : this.email;
536	        String householdPart = this.householdId == null ? "" : this.householdId;
537	        return telephonePart + "|" + emailPart + "|" + householdPart;
538	    }
539	
540	    /**
541	     * City -> canonical region, the fixed ground truth for deriving locality.
542	     */
543	    private static final Map<String, String> CITY_REGION = Map.of(
544	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
545	
546	    /**
547	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
548	     * deriving locality from the postcode ahead of the city.
549	     */
550	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
551	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
552	
553	    /**
554	     * The owner's locality: the canonical region resolved by the postcode range first
555	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
556	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
557	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
558	     * when the city is not in the table either. The postcode takes precedence so cities that share a
559	     * name are disambiguated by their postcode's region.
560	     *
561	     * @return the canonical region string, or {@code "UNKNOWN"}
562	     */
563	    public String getLocality() {
564	        String byPostcode = regionForPostcode(this.postcode);
565	        if (byPostcode != null) {
566	            return byPostcode;
567	        }
568	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
569	    }
