573	     * its locality.
574	     */
575	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
576	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
577	
578	    /**
579	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
580	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
581	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
582	     * (e.g. {@code "UNKNOWN"}).
583	     *
584	     * @return the IANA timezone name, or {@code null}
585	     */
586	    public String getTimezone() {
587	        return REGION_TIMEZONE.get(getLocality());
588	    }
589	
590	    /**
591	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
592	     * absent, not a 4-digit number, or in no known range.
593	     *
594	     * @param postcode the owner's postcode (may be {@code null})
595	     * @return the matching region, or {@code null}
596	     */
597	    private static String regionForPostcode(String postcode) {
598	        if (postcode == null || !postcode.matches("\\d{4}")) {
599	            return null;
600	        }
601	        int value = Integer.parseInt(postcode);
602	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
603	            int[] range = entry.getValue();
604	            if (value >= range[0] && value <= range[1]) {
605	                return entry.getKey();
606	            }
607	        }
608	        return null;
609	    }
610	
611	    protected Set<Pet> getPetsInternal() {
612	        if (this.pets == null) {
613	            this.pets = new HashSet<>();
614	        }
615	        return this.pets;
616	    }
617	
618	    protected void setPetsInternal(Set<Pet> pets) {
619	        this.pets = pets;
620	    }
621	
622	    public List<Pet> getPets() {
623	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
624	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
625	        return Collections.unmodifiableList(sortedPets);
626	    }
627	
628	    public void setPets(List<Pet> pets) {
629	        this.pets = new HashSet<>(pets);
630	    }
631	
632	    public void addPet(Pet pet) {
633	        getPetsInternal().add(pet);
634	        pet.setOwner(this);
635	    }
636	
637	    /**
638	     * Return the Pet with the given name, or null if none found for this Owner.
639	     *
640	     * @param name to test
641	     * @return true if pet name is already in use
642	     */
643	    public Pet getPet(String name) {
644	        return getPet(name, false);
645	    }
646	
647	    /**
648	     * Return the Pet with the given name, or null if none found for this Owner.
649	     *
650	     * @param name to test
651	     * @return true if pet name is already in use
652	     */
653	    public Pet getPet(String name, boolean ignoreNew) {
654	        name = name.toLowerCase();
655	        for (Pet pet : getPetsInternal()) {
656	            if (!ignoreNew || !pet.isNew()) {
657	                String compName = pet.getName();
658	                compName = compName.toLowerCase();
659	                if (compName.equals(name)) {
660	                    return pet;
661	                }
662	            }
663	        }
664	        return null;
665	    }
666	
667	    public Pet getPet(Integer petId) {
668	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
669	    }
670	
671	    @Override
672	    public String toString() {
673	        return new ToStringCreator(this)
674	
675	            .append("id", this.getId())
676	            .append("new", this.isNew())
677	            .append("lastName", this.getLastName())
678	            .append("firstName", this.getFirstName())
679	            .append("address", this.address)
680	            .append("city", this.city)
681	            .append("telephone", this.telephone)
682	            .append("email", this.email)
683	            .toString();
684	    }
685	}
